/*
** Genuine original-LuaJIT v2 imports must preserve owner/closure identity.
** The checked fixtures are regenerated by generate_legacy_bytecode_fixtures.py
** with an original LuaJIT, never by this fork's v4 string.dump implementation.
** Run from the repository root (or pass its tests/fixtures directory).
*/
#include <assert.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "lua.h"
#include "lauxlib.h"
#include "lualib.h"
#include "lib/lua_fixture_helpers.h"

typedef struct Bytes { char *p; size_t size, cap, pos; } Bytes;

static const char *gc_reader(lua_State *L, void *ud, size_t *size)
{
  Bytes *b = (Bytes *)ud;
  size_t n = b->size-b->pos;
  if (n > 17) n = 17;
  *size = n;
  if (!n) return NULL;
  /* Exercise opaque prototype anchors across nested constants and debug data. */
  (void)lua_gc(L, LUA_GCCOLLECT, 0);
  b->pos += n;
  return b->p+b->pos-n;
}

static int writer(lua_State *L, const void *p, size_t size, void *ud)
{
  Bytes *b = (Bytes *)ud;
  (void)L;
  if (b->size+size > b->cap) {
    size_t cap = b->cap ? b->cap*2 : 256;
    char *out;
    while (cap < b->size+size) cap *= 2;
    out = (char *)realloc(b->p, cap);
    assert(out != NULL);
    b->p = out; b->cap = cap;
  }
  memcpy(b->p+b->size, p, size);
  b->size += size;
  return 0;
}

static Bytes fixture(const char *dir, const char *name)
{
  Bytes b = {NULL, 0, 0, 0};
  char path[1024];
  FILE *f;
  long size;
  int n = snprintf(path, sizeof(path), "%s/%s", dir, name);
  assert(n > 0 && (size_t)n < sizeof(path));
  f = fopen(path, "rb");
  assert(f != NULL);
  assert(fseek(f, 0, SEEK_END) == 0);
  size = ftell(f);
  assert(size > 5 && size < 100000);
  rewind(f);
  b.cap = b.size = (size_t)size;
  b.p = (char *)malloc(b.size);
  assert(b.p != NULL);
  assert(fread(b.p, 1, b.size, f) == b.size);
  assert(fclose(f) == 0);
  assert(memcmp(b.p, "\033LJ\002", 4) == 0);
  return b;
}

static void run_loaded(lua_State *L, unsigned count)
{
  unsigned i;
  for (i=0; i<count; i++) {
    lua_pushvalue(L, -1);
    ljt_lua_pcall(L, 0, 1, "run stock-v2 cell fixture");
    assert(lua_toboolean(L, -1));
    lua_pop(L, 1);
  }
}

static void check_fixture(lua_State *L, const char *dir, const char *name,
                          unsigned count)
{
  Bytes b = fixture(dir, name), dump = {NULL, 0, 0, 0};
  ljt_lua_assert_ok(L, lua_load(L, gc_reader, &b, name), "load stock-v2 fixture");
  run_loaded(L, count);
  assert(lua_dump(L, writer, &dump) == 0);
  assert(dump.size > 5 && (unsigned char)dump.p[3] == 4);
  lua_pop(L, 1);
  ljt_lua_assert_ok(L, lua_load(L, gc_reader, &dump, "=normalized-v4"),
                   "reload normalized v4 fixture");
  run_loaded(L, count);
  lua_pop(L, 1);
  free(dump.p); free(b.p);
  assert(lua_gettop(L) == 0);
}

static void check_truncated(lua_State *L, const char *dir)
{
  Bytes b = fixture(dir, "legacy-bytecode-cells.bc");
  size_t end = b.size, n;
  for (n=1; n<end; n+=31) {
    b.size = n; b.pos = 0;
    assert(lua_load(L, gc_reader, &b, "=truncated-v2") != 0);
    lua_pop(L, 1);
    (void)lua_gc(L, LUA_GCCOLLECT, 0);
  }
  free(b.p);
}

/* Cross-mode bytecode remains dumpable without becoming executable. */
static void check_non_native(lua_State *L, const char *dir)
{
  Bytes b = fixture(dir, "legacy-bytecode-fr1.bc");
  const char *dump;
  size_t size;
  ljt_lua_assert_ok(L, lua_loadx(L, gc_reader, &b, "=fr1-v2", "bW"),
                   "load non-native v2 fixture");
  lua_getglobal(L, "string");
  lua_getfield(L, -1, "dump");
  lua_remove(L, -2);
  lua_pushvalue(L, -2);
  ljt_lua_pcall(L, 1, 1, "dump non-native v4 fixture");
  dump = lua_tolstring(L, -1, &size);
  assert(size > 5 && (unsigned char)dump[3] == 4 && !(dump[4] & 8));
  ljt_lua_assert_ok(L, luaL_loadbufferx(L, dump, size, "=fr1-v4", "bW"),
                   "reload non-native v4 fixture");
  lua_pop(L, 3);
  free(b.p);
}

static void check_frame_limit(lua_State *L, const char *dir)
{
  Bytes b = fixture(dir, "legacy-bytecode-wide-frame.bc");
  assert(lua_load(L, gc_reader, &b, "=wide-frame-v2") != 0);
  assert(strstr(lua_tostring(L, -1), "function or expression too complex"));
  lua_pop(L, 1);
  free(b.p);
}

int main(int argc, char **argv)
{
  static const char *const names[] = {
    "legacy-bytecode-cells-stripped.bc", "legacy-bytecode-cells-stripped-be.bc",
    "legacy-bytecode-cells.bc", "legacy-bytecode-cells-be.bc",
    "legacy-bytecode-debug.bc", "legacy-bytecode-debug-be.bc",
    "legacy-bytecode-lines-300.bc", "legacy-bytecode-lines-300-be.bc",
    "legacy-bytecode-lines-70000.bc", "legacy-bytecode-lines-70000-be.bc"
  };
  const char *dir = argc > 1 ? argv[1] : "tests/fixtures";
  char rootdir[1024];
  const char *root = getenv("LJ_TEST_ROOT");
  lua_State *L = ljt_lua_newstate_openlibs();
  unsigned phase, i;
  if (argc <= 1 && root) {
    int n = snprintf(rootdir, sizeof(rootdir), "%s/tests/fixtures", root);
    assert(n > 0 && (size_t)n < sizeof(rootdir));
    dir = rootdir;
  }
  for (phase=0; phase<2; phase++) {
    if (phase)
      ljt_lua_dostring(L, "assert(require('threading').spawn(function() return true end):join())");
    for (i=0; i<sizeof(names)/sizeof(names[0]); i++)
      check_fixture(L, dir, names[i], 40);
    check_truncated(L, dir);
    check_frame_limit(L, dir);
    check_non_native(L, dir);
  }
  check_fixture(L, dir, "legacy-bytecode-sharing-stripped.bc", 3);
  check_fixture(L, dir, "legacy-bytecode-sharing-stripped-be.bc", 3);
  lua_close(L);
  puts("legacy bytecode cells: OK");
  return 0;
}
